DROP TABLE IF EXISTS `item_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `item_template` (
  `id` int(11) NOT NULL,
  `TYPE` int(11) NOT NULL,
  `gender` smallint(6) NOT NULL,
  `NAME` varchar(255) NOT NULL,
  `description` varchar(255) NOT NULL,
  `level` int(11) NOT NULL DEFAULT 0,
  `icon_id` int(11) NOT NULL,
  `part` int(11) NOT NULL,
  `is_up_to_up` tinyint(1) NOT NULL,
  `power_require` bigint(20) NOT NULL,
  `gold` int(11) NOT NULL DEFAULT 0,
  `gold_sell` int(11) NOT NULL DEFAULT 0,
  `gem` int(11) NOT NULL DEFAULT 0,
  `gem_sell` int(11) NOT NULL DEFAULT 0,
  `ruby` int(11) NOT NULL DEFAULT 0,
  `ruby_sell` int(11) NOT NULL DEFAULT 0,
  `head` int(11) NOT NULL DEFAULT -1,
  `body` int(11) NOT NULL DEFAULT -1,
  `leg` int(11) NOT NULL DEFAULT -1,
  `TypeEvent` int(11) NOT NULL DEFAULT 0,
  `isGender` tinyint(1) NOT NULL,
  `dung_duoc` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Đánh dấu thủ công trong panel: vật phẩm này còn dùng được hay không',
  `aura_id` smallint(6) NOT NULL DEFAULT -1 COMMENT 'Mặc cải trang này thì hiện hào quang có id đó; -1 = không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
