INSERT INTO `panel_config` VALUES ('boss_giay_hoi_sinh','3600',NULL),('boss_hsd_max','0','Trang bị rơi từ boss: HẠN SỬ DỤNG nhiều nhất (ngày) — 0 là tắt'),('boss_hsd_min','0','Trang bị rơi từ boss: HẠN SỬ DỤNG ít nhất (ngày) — 0 là tắt, đồ vĩnh viễn như cũ'),('boss_hsd_vinh_vien','0','Tỉ lệ % món rơi từ boss là VĨNH VIỄN (không có hạn) — chỉ có tác dụng khi đã đặt HSD ở trên'),('boss_spawn_da_gieo','1',NULL),('boss_theo_map_da_gieo','1',NULL),('dang_ky_tu_dong','1','Cho đăng ký tài khoản ngay ở màn login (1 = bật, 0 = tắt)'),('dang_nhap_cho_giay','5','Thời gian phải chờ trước khi đăng nhập lại (giây) — 0 là tắt'),('doi_khu_giay','8','Giãn cách giữa hai lần đổi khu (giây) — 0 là tắt'),('doi_tv_bat','1','Bật chức năng đổi VND sang Thỏi Vàng (1 = bật, 0 = tắt)'),('doi_tv_min','1000','Số VND tối thiểu mỗi lần đổi'),('doi_tv_moi_1k','5','Số Thỏi Vàng nhận được cho mỗi 1.000 VND'),('giao_dich_cho_giay','15','Giãn cách giữa hai lần giao dịch (giây) — 0 là tắt'),('giu_lich_su_gd_ngay','30','Số ngày giữ nhật ký giao dịch giữa người chơi — 0 là giữ mãi'),('hien_ten_map','0','MẶC ĐỊNH TẮT — dòng này dùng slot 8 của gói 65 mà client chỉ biết slot 0..7, bật lên là client hỏng (không đánh được quái bằng phím Enter / nháy đúp). Chỉ bật nếu đã vá client.'),('loi_chao_vao_game','Server mở ra nhằm mục đích học tập, không mua bán, kinh doanh !','L?i ch?o hi?n ra khi v?a v?o game ? d? tr?ng l? kh?ng hi?n g?'),('mat_khau_admin','01122003','Mật khẩu Quyền Điều Hành Hệ Thống (gõ ở NPC trong game)'),('mo_panel_khi_dung_pass','1','Nhập đúng mật khẩu quản trị trong game thì mở panel (1 = bật, 0 = tắt)'),('nv_moi_hong_ngoc','0','Hồng ngọc của nhân vật mới tạo'),('nv_moi_ngoc','0','Ngọc xanh của nhân vật mới tạo'),('nv_moi_vang','2000','Vàng của nhân vật mới tạo'),('skh_bat','1','Bật rơi đồ set kích hoạt (vải thô) từ quái (1 = bật, 0 = tắt)'),('skh_chi_tu_panel','0',''),('skh_map','1,8,15','Map cho rơi đồ set kích hoạt, id ngăn bằng dấu phẩy — trống là giữ luật cũ'),('skh_mota_mau','0','MÀU chữ mô tả set trên món đồ: 0 đen đậm, 1 xanh lá đậm, 2 xanh dương đậm, 3 đỏ, 4 xanh lá, 5 xanh dương, 7 đỏ đậm, 8 vàng đậm, -1 mặc định. Đổi rồi bấm \"Áp kiểu dòng mô tả\"'),('skh_mota_type','0','Loại (type) của dòng chữ mô tả set. Game dùng 0, 1, 2, 4, 5, 6, 7, 9, 10 — không đổi màu chữ, màu xem khoá skh_mota_mau'),('skh_sao_bat','1','Gắn sao pha lê vào đồ set kích hoạt rơi ra (1 = bật, 0 = tắt)'),('skh_sao_max','3','Số sao pha lê nhiều nhất'),('skh_sao_min','1','Số sao pha lê ít nhất'),('skh_sao_tile','10','Tỉ lệ món đồ set kích hoạt rơi ra có sao pha lê (%)'),('skh_so_ngay','0','Số ngày kể từ khi tạo tài khoản còn nhận được set kích hoạt — 0 là không giới hạn'),('skh_tile','100','Tỉ lệ giết một quái rơi một món đồ set kích hoạt (%)'),('skh_tile_full','',''),('skh_tile_thuong','',''),('tl_exp','0.2','Hệ số tiềm năng — 1 là như gốc, 10 là gấp mười'),('tl_vang','0.1','Hệ số vàng rơi từ quái — 1 là như gốc'),('vang_roi_max','0','Vàng rơi NHIỀU NHẤT mỗi lần — 0 là dùng trần mặc định (300.000 × hệ số vàng)'),('vang_roi_min','0','Vàng rơi ÍT NHẤT mỗi lần — 0 là không đặt sàn'),('ve_thang_gia','100000','Giá vé tháng (VND)'),('ve_thang_ngay','30','Số ngày hiệu lực của vé tháng'),('ve_tuan_gia','30000','Giá vé tuần (VND)'),('ve_tuan_ngay','7','Số ngày hiệu lực của vé tuần'),('vs_data','44','Phiên bản gói dữ liệu (part, hiệu ứng, ảnh) — TĂNG khi thêm cải trang / phụ kiện'),('vs_item','41','Phiên bản bảng vật phẩm — TĂNG khi thêm/sửa item_template'),('vs_map','2','Phiên bản bản đồ'),('vs_skill','62','Phiên bản kỹ năng');
/*!40000 ALTER TABLE `panel_config` ENABLE KEYS */;
UNLOCK TABLES;

