INSERT INTO `task_main_template` VALUES (0,'Nhiệm vụ đầu tiên','Chi tiết nhiệm vụ'),(1,'Nhiệm vụ tập luyện','Mộc nhân được đặt nhiều tại %1, ngay trước nhà %2\nHãy đánh ngã 5 mộc nhân, \nsau đó quay về nhà báo cáo với ông %2\nĐể đánh, hãy chạm nhanh 2 lần vào đối tượng\nThưởng 500 sức mạnh\nThưởng 500 tiềm năng\n'),(2,'Nhiệm vụ tìm thức ăn','Tìm đến %3, tiêu diệt bọn quái %4 và nhặt về 10 đùi gà\nThưởng 1 k sức mạnh\nThưởng 1 k tiềm năng\nHọc được kỹ năng bay\n'),(3,'Nhiệm vụ sao băng','Đi khám phá xem vật thể lạ vừa rơi xuống hành tinh\nThưởng 2 k sức mạnh\nThưởng 2 k tiềm năng\n'),(4,'Nhiệm vụ thử thách','Khủng long mẹ sống tại Trái Đất\nLợn lòi mẹ sống tại Namếc\nQuỷ đất mẹ sống tại Xayda\nDùng tàu vũ trụ để di chuyển sang hành tinh khác\nThưởng 4 k sức mạnh\nThưởng 4 k tiềm năng\n'),(5,'Nhiệm vụ thử thách','Lợn lòi mẹ sống tại Namếc\nKhủng long mẹ sống tại Trái Đất\nQuỷ đất mẹ sống tại Xayda\nDùng tàu vũ trụ để di chuyển sang hành tinh khác\nThưởng 4 k sức mạnh\nThưởng 4 k tiềm năng\n'),(6,'Nhiệm vụ thử thách','Quỷ đất mẹ sống tại Xayda\nKhủng long mẹ sống tại Trái Đất\nLợn lòi mẹ sống tại Namếc\nDùng tàu vũ trụ để di chuyển sang hành tinh khác\nThưởng 4 k sức mạnh\nThưởng 4 k tiềm năng\n'),(7,'Nhiệm vụ giải cứu','Đến khu vực %13,\nHạ 20 con %9\nThưởng 8 k sức mạnh\nThưởng 8 k tiềm năng\n'),(8,'Nhiệm vụ tìm ngọc','Ngọc rồng 7 sao đang bị bọn\n%14 cướp đi.\nĐánh bại chúng để tìm lại.\nThưởng 15 k sức mạnh\nThưởng 15 k tiềm năng\n'),(9,'Nhiệm vụ tìm ngọc','Tìm đường đến Karin\nnói chuyện với Bò Mộng\nkhi đụng độ Tàu Pảy Pảy hãy mau chóng bay lên tháp karin\n'),(10,'Nhiệm vụ tìm ngọc','Học võ với Thần Mèo\nXuống rừng Karin tiêu diệt Tàu Pảy Pảy\nđem ngọc về cho ông %2\nThưởng 15 k sức mạnh\nThưởng 15 k tiềm năng\n'),(11,'Nhiệm vụ bái sư','Tìm đường tới %11, trò chuyện với %10 và xin làm đệ tử\r\n'),(12,'Nhiệm vụ gia nhập bang hội','Báo cáo với %2 khi bang của bạn\ncó từ 5 thành viên trở lên\nThưởng 20 k sức mạnh\nThưởng 20 k tiềm năng\n'),(13,'Nhiệm vụ bang hội đầu tiên','Cùng phối hợp với 1 người đồng đội lên đường làm nhiệm vụ\nGợi ý:\nHeo rừng xuất hiện tại rừng Bamboo\nHeo da xanh xuất \nhiện tại núi hoa vàng\nHeo xayda xuất hiện tại rừng cọ\nHãy tới trạm tàu vũ trụ để có thể di chuyển qua các map\n'),(14,'Nhiệm vụ bái sư','Đánh bọn %12 để lấy truyện\nDoremon tập 2\nThưởng 80 k sức mạnh\nThưởng 80 k tiềm năng\n\n'),(15,'Nhiệm vụ bang hội thứ 2','Cùng ít nhất 2 thành viên trong\r\nbang tiêu diệt\r\nBulon tại Đảo Bulông(Trái Đất)\r\nUkulele tại Đông Nam Guru(Namếc)\r\nQuỷ mập tại Bờ Vực Đen(Xayda)\r\nThưởng 150 k sức mạnh\r\nThưởng 150 k tiềm năng\r\n'),(16,'Nhiệm vụ thách đấu','Thách đấu và chiến thằng 10 người\r\nbất kì\r\nThưởng 150 k sức mạnh\r\nThưởng 150 k tiềm năng\r\n\r\n'),(17,'Nhiệm vụ tiêu diệt Boss Trùm','Đạt 1.500.000 sức mạnh để trở\nthành Siêu nhân\nTiêu diệt Akkuman tại Thành\nphố Vegeta, tiêu diệt Tamborine tại Đông\nKarin, tiêu diệt Drum tại Thung\nlũng Namếc\nThưởng 200 k sức mạnh\nThưởng 200 k tiềm năng\n'),(18,'Nhiệm vụ thử thách','Đạt 5 triệu sức mạnh\nTham gia và chiến thắng vòng 2 đại hội\nvõ thuật tại Vách núi Kakarot\nThưởng 500 k sức mạnh\nThưởng 500 k tiềm năng\n'),(19,'Nhiệm vụ cam go','Đạt 15 triệu sức mạnh\nVào doanh trại Độc Nhãn tìm diệt\nTrung Úy Trắng\nThưởng 5 Tr sức mạnh\nThưởng 5 Tr tiềm năng\n'),(20,'Nhiệm vụ bất khả thi','Đạt 50 triệu sức mạnh\nTiêu diệt bọn tay sai của Fide tại Xayda\nThưởng 50 Tr sức mạnh\nThưởng 50 Tr tiềm năng\n'),(21,'Nhiệm vụ tìm diệt đệ tử','Tiêu diệt bọn đệ tử Kuku, Mập Đầu Đinh,\nRambo của Fide đại ca tại Xayda\nCui có thể biết vị trí của chúng, nếu tìm\nkhông thấy hãy đến gặp Cui tại thành\nphố Vegeta\nThưởng 200 Tr sức mạnh\nThưởng 200 Tr tiềm năng\n\n'),(22,'Tiểu đội sát thủ','Tiêu diệt Tiểu Đội Sát Thủ do Fide đại\nca gọi đến tại Xayda\nThưởng 250 Tr sức mạnh\nThưởng 250 Tr tiềm năng\n'),(23,'Fide đại ca','Fide đã xuất hiện tại núi khỉ vàng\nThưởng 300 Tr sức mạnh\nThưởng 300 Tr tiềm năng\n\n\n'),(24,'Chú bé đến từ tương lai','Đến trái đất, rừng bamboo, rừng dương\nxỉ, nam Kamê tìm người lạ\nĐến đảo rùa đưa thuốc cho Quy Lão\nTheo Ca Lích đến tương lai\nGiúp họ diệt bọn bọ hung con\nThưởng 100 Tr sức mạnh\nThưởng 100 Tr tiềm năng\n\n'),(25,'Chạm trán Rôbốt Sát Thủ lần 1','Hãy đến thành phố phía nam\nđảo balê hoặc cao nguyên\nCùng 2 đồng bang diệt 900 Xên con cấp 3\nBáo với Bunma tương lai\nThưởng 400 Tr sức mạnh\nThưởng 400 Tr tiềm năng\n\n'),(26,'Chạm trán Rôbốt Sát Thủ lần 2','Trở về quá khứ, đến sân sau siêu thị\nTiêu diệt bọn Rôbốt sát thủ\nBáo với Bunma tương lai\nThưởng 500 Tr sức mạnh\nThưởng 500 Tr tiềm năng\n'),(27,'Chạm trán Rôbốt Sát Thủ lần 3','Đến thành phố, ngọn núi, thung lũng phía Bắc\nTiêu diệt bọn Rôbốt sát thủ\nCùng 2 đồng bang diệt 800 Xên con cấp 5\nBáo với Bunma tương lai\nThưởng 650 Tr sức mạnh\nThưởng 650 Tr tiềm năng\n\n'),(28,'Chạm trán Xên bọ hung','Đến thị trấn Ginder\nTiêu diệt Xên Bọ Hung cấp 1\nTiêu diệt Xên Bọ Hung cấp 2\nTiêu diệt Xên Bọ Hung hoàn thiện\nCùng 2 đồng bang diệt 700 Xên con cấp 8\nBáo với Bunma tương lai\nThưởng 800 Tr sức mạnh\nThưởng 800 Tr tiềm năng\n'),(29,'Cuộc dạo chơi của Xên','Nâng sức đánh gốc lên 10K, đến gặp thần\nmèo\nThu thập Capsule kì bí\nĐến võ đài Xên Bọ Hung\nTiêu diệt 7 đứa con của Xên\nTiêu diệt Siêu Bọ Hung\nBáo với Bunma tương lai\nThưởng 1,2 Tỷ sức mạnh\nThưởng 1,2 Tỷ tiềm năng\n'),(30,'Cuộc đối đầu không cân sức','Cẩn thận !!!\nNhững vị khách không mời mà tới\nthường tỏ ra nguy hiểm\n'),(31,'Chạm trán người ngoài hành tinh','Bảo vệ hành tinh thực vật, hạ những kẻ xâm lược.\nThưởng 1,5 Tỷ sức mạnh\nThưởng 1,5 Tỷ tiềm năng\nThưởng cái con cặc'),(32,'Vui lòng chờ nhiệm vụ mới','Vui lòng chờ nhiệm vụ mới');
/*!40000 ALTER TABLE `task_main_template` ENABLE KEYS */;
